const appt = $input.first().json;
if (!appt || !appt.id) { throw new Error('Appointment not found'); }

const client = appt.profiles || {};
const services = (appt.appointment_services || []).map(s => s.services?.name).filter(Boolean);
const serviceNames = services.join(', ') || 'Servicio LAP';

const dateStr = appt.appointment_date;
const startDT = `${dateStr}T${appt.start_time}`;
const endDT = `${dateStr}T${appt.end_time}`;

const toIcsDT = (d, t) => `${d.replace(/-/g,'')}T${t.replace(/:/g,'').slice(0,6)}`;
const icsStart = toIcsDT(dateStr, appt.start_time);
const icsEnd = toIcsDT(dateStr, appt.end_time);

const encode = encodeURIComponent;
const gcalUrl = `https://calendar.google.com/calendar/render?action=TEMPLATE&text=${encode('Servicio LAP: ' + serviceNames)}&dates=${icsStart}/${icsEnd}&location=${encode(appt.location_address || '')}&details=${encode('Cita confirmada con LAP Services Panama.')}`;

return [{
  json: {
    appointment_id: appt.id,
    client_name: client.name || 'Cliente',
    client_email: client.email,
    client_phone: client.phone,
    date: dateStr,
    start_time: appt.start_time,
    end_time: appt.end_time,
    start_dt: startDT,
    end_dt: endDT,
    ics_start: icsStart,
    ics_end: icsEnd,
    location: appt.location_address || '',
    notes: appt.notes || '',
    service_names: serviceNames,
    summary: `Servicio LAP: ${serviceNames} - ${client.name || ''}`.trim(),
    description: `Servicios: ${serviceNames}\n\nCliente: ${client.name}\nTelefono: ${client.phone || 'n/a'}\n\nNotas: ${appt.notes || 'Ninguna'}\n\nVer cita: https://lapservicepty.com/admin/citas/${appt.id}`,
    gcal_template_url: gcalUrl
  }
}];

const p = $('Build Payload').item.json;
const pad = n => String(n).padStart(2,'0');
const now = new Date();
const dtstamp = `${now.getUTCFullYear()}${pad(now.getUTCMonth()+1)}${pad(now.getUTCDate())}T${pad(now.getUTCHours())}${pad(now.getUTCMinutes())}${pad(now.getUTCSeconds())}Z`;

const ics = ['BEGIN:VCALENDAR', 'VERSION:2.0', 'PRODID:-//LAP Services//Panama//ES', 'CALSCALE:GREGORIAN', 'METHOD:PUBLISH', 'BEGIN:VEVENT', `UID:${p.appointment_id}@lapservicepty.com`, `DTSTAMP:${dtstamp}`, `DTSTART;TZID=America/Panama:${p.ics_start}`, `DTEND;TZID=America/Panama:${p.ics_end}`, `SUMMARY:${p.summary}`, `LOCATION:${p.location.replace(/,/g,',')}", `DESCRIPTION:${p.description.replace(/\n/g,'\\n').replace(/,/g,',')}", 'STATUS:CONFIRMED', 'END:VEVENT', 'END:VCALENDAR'].join('\r\n');

return [{
  json: {...p, ics_content: ics, ics_filename: `LAP-cita-${p.appointment_id}.ics`, ics_base64: Buffer.from(ics, 'utf-8').toString('base64')}
}];

const payload = $('Build Payload').item.json;
let ics = null;
try { ics = $('Generate ICS fallback').item.json; } catch (e) { ics = null; }

const isFallback = !!(ics && ics.ics_content);
const fecha = new Date(payload.date + 'T12:00:00').toLocaleDateString('es-PA', { weekday: 'long', day: 'numeric', month: 'long', year: 'numeric' });
const hora = payload.start_time ? payload.start_time.slice(0,5) : '';
const horaFin = payload.end_time ? payload.end_time.slice(0,5) : '';
const calendarNote = isFallback ? '<p><b>Google Calendar no pudo crear el evento automáticamente.</b> Usa el botón de abajo para agregarlo manualmente.</p>' : '<p>✓ El evento fue creado en Google Calendar y le enviamos la invitación al cliente. Si no ves el evento, usa el botón de abajo.</p>';

const clientSubject = `Tu cita con LAP Services está confirmada — ${fecha}`;
const clientHtml = `<div style="font-family:Arial,sans-serif;max-width:600px;margin:0 auto;"><div style="background:linear-gradient(135deg,#2E7D32,#4CAF50);padding:24px;text-align:center;color:white;"><h1 style="margin:0">LAP Services Panamá</h1></div><div style="padding:24px;background:#f7faf7;"><p>Hola <b>${payload.client_name}</b>,</p><p>Tu cita con los siguientes detalles:</p><table style="width:100%;border-collapse:collapse;margin:16px 0;"><tr><td style="padding:8px;border-bottom:1px solid #e0e0e0;"><b>Servicios</b></td><td style="padding:8px;border-bottom:1px solid #e0e0e0;">${payload.service_names}</td></tr><tr><td style="padding:8px;border-bottom:1px solid #e0e0e0;"><b>Fecha</b></td><td style="padding:8px;border-bottom:1px solid #e0e0e0;">${fecha}</td></tr><tr><td style="padding:8px;border-bottom:1px solid #e0e0e0;"><b>Hora</b></td><td style="padding:8px;border-bottom:1px solid #e0e0e0;">${hora} – ${horaFin}</td></tr><tr><td style="padding:8px;"><b>Dirección</b></td><td style="padding:8px;">${payload.location}</td></tr></table><p style="text-align:center;margin:24px 0;"><a href="${payload.gcal_template_url}" style="background:#2E7D32;color:white;padding:12px 24px;text-decoration:none;border-radius:8px;display:inline-block;">📅 Agregar a Google Calendar</a></p></div></div>`;

const adminSubject = `[LAP Admin] Cita confirmada: ${payload.client_name} — ${fecha}`;
const adminHtml = `<div style="font-family:Arial,sans-serif;max-width:600px;margin:0 auto;"><div style="background:#1B5E20;padding:20px 24px;color:white;"><h2 style="margin:0">LAP Admin — Cita Confirmada</h2></div><div style="padding:24px;background:#f1f8e9;"><h3 style="margin:0 0 16px;color:#1B5E20;">📋 Detalles de la Cita</h3><table style="width:100%;border-collapse:collapse;margin-bottom:16px;"><tr><td style="padding:8px;border-bottom:1px solid #c8e6c9;"><b>Cliente</b></td><td style="padding:8px;border-bottom:1px solid #c8e6c9;">${payload.client_name}</td></tr><tr><td style="padding:8px;border-bottom:1px solid #c8e6c9;"><b>Email</b></td><td style="padding:8px;border-bottom:1px solid #c8e6c9;"><a href="mailto:${payload.client_email}">${payload.client_email}</a></td></tr><tr><td style="padding:8px;border-bottom:1px solid #c8e6c9;"><b>Servicios</b></td><td style="padding:8px;border-bottom:1px solid #c8e6c9;">${payload.service_names}</td></tr><tr><td style="padding:8px;border-bottom:1px solid #c8e6c9;"><b>Fecha</b></td><td style="padding:8px;border-bottom:1px solid #c8e6c9;">${fecha}</td></tr></table>${calendarNote}<p style="text-align:center;margin:20px 0;"><a href="${payload.gcal_template_url}" style="background:#1B5E20;color:white;padding:12px 24px;text-decoration:none;border-radius:8px;display:inline-block;">📅 Agregar a Google Calendar</a></p></div></div>`;

return [{json: {...payload, client_subject: clientSubject, client_html: clientHtml, admin_subject: adminSubject, admin_html: adminHtml, is_fallback: isFallback, attach_ics: isFallback, ics_content: ics ? ics.ics_content : null, ics_filename: ics ? ics.ics_filename : null}}];
